stage_clear=Class(object)

function stage_clear:init(stgct)
	self.x=0
	self.y=112
	self.group=GROUP_GHOST
	self.layer=LAYER_TOP
	self.size=size
	self.t=0
	self.hscale=1
	self.vscale=1
	self.bonus=(lstg.var.lifeleft*10000+lstg.var.bomb*1000)*combo.max*stgct
	self.cmax0=combo.max
end

function stage_clear:frame()
	if self.timer<30 then
		self.t=self.timer/30
	elseif self.timer<=130 then
		self.t=1
		combo.max=math.floor(self.cmax0-self.cmax0*(self.timer-30)/100)
		combo.value=min(combo.value,combo.max)
		combo.real=combo.value
		if self.timer%4==0 then PlaySound('nodamage', 0.2) end
		lstg.var.score=lstg.var.score+self.bonus/100
	elseif self.timer<160 then
		self.t=(160-self.timer)/30
	else
		Del(self)
	end
end

function stage_clear:render()
	SetFontState('score3','',Color(self.t*255,255,255,255))
	RenderText('score3','Stage Clear Bonus',self.x,self.y,0.7,'centerpoint')
	RenderScore('score3',self.bonus,self.x,self.y-41,0.7,'centerpoint')
	object.render(self)
end
