_tmp_sc=boss.card.New("",1,1,49,2400,{0,0,22},false)
function _tmp_sc:init()
    self.hitters={}
    lasttask=task.New(self,function()
        do local x,_d_x=(-192),(396) for _=1,2 do
            do local y,_d_y=(32),(64) for _=1,4 do
                last=New(_editor_class["1p1-point"],self.x,self.y,x,y,self)
                local o = last
                table.insert(self.hitters, o)
                do local sc,_d_sc=(1/8),(1/8) for _=1,7 do
                    last=New(_editor_class["1p1-chain"],self.x,self.y,self,o,sc)
                sc=sc+_d_sc end end
            y=y+_d_y end end
        x=x+_d_x end end
        lasttask=task.New(self,function()
            local aa = 90
            do for _=1,_infinite do
                local f0 = 2
                local f = 1
                do local hdx0,_d_hdx0=(1),(4) for _=1,2 do
                    f = 1
                    do local hdx,_d_hdx=(hdx0),(1) for _=1,4 do
                        if IsValid(self.hitters[hdx]) then f=0 end
                    hdx=hdx+_d_hdx end end
                    f0=f0-f
                hdx0=hdx0+_d_hdx0 end end
                if f0<2 then
                    do local hdx0,_d_hdx0=(1),(4) for _=1,2 do
                        do local hdx,_d_hdx=(hdx0),(1) for _=1,4 do
                            if IsValid(self.hitters[hdx]) then
                                _del(self.hitters[hdx],true)
                            else
                            end
                        hdx=hdx+_d_hdx end end
                    hdx0=hdx0+_d_hdx0 end end
                    self.hp=-1
                else
                end
                task._Wait(1)
            end end
        end)
        task.MoveTo(0,112,60,MOVE_ACC_DEC)
        local sc = 0
        lasttask=task.New(self,function()
            do local ap,_d_ap=(1),(1) for _=1,90 do
                sc=sin(ap)
                task._Wait(1)
            ap=ap+_d_ap end end
            do local ap,_d_ap=(90.7),(0.7) for _=1,_infinite do
                sc=0.7+0.3*sin(ap)
                task._Wait(1)
            ap=ap+_d_ap end end
        end)
        lasttask=task.New(self,function()
            do local a,_d_a=(90),(2) for _=1,_infinite do
                self.x=sc*96*cos(a); self.y=112+sc*32*sin(a); 
                task._Wait(1)
            a=a+_d_a end end
        end)
        do for _=1,_infinite do
            do
                do local n,_d_n=(1),(0) for _=1,4 do
                    do local a,_d_a=(ran:Float(0,360)),(6) local s,_d_s=(1),(1) for _=1,60 do
                        last=New(_straight,ball_mid,COLOR_BLUE,self.x,self.y,1.5+0.2*(s%2),a,false,3,true,true,0,false,0,0,0,false)
                    a=a+_d_a s=s+_d_s end end
                    do local sc,_d_sc=(1/15),(1/15) local v,_d_v=(2.5),(0.2) for _=1,15 do
                        PlaySound("tan00",0.1,self.x/256,false)
                        do local hdx0,_d_hdx0=(1),(4) for _=1,2 do
                            do local hdx,_d_hdx=(hdx0),(1) for _=1,4 do
                                if IsValid(self.hitters[hdx]) then
                                    local o = self.hitters[hdx]
                                    _create_bullet_group(grain_a,COLOR_PURPLE,o.x*sc+self.x*(1-sc),o.y*sc+self.y*(1-sc),n,0,v,v,0,90,true,0,true,true,0,false,self)
                                else
                                end
                            hdx=hdx+_d_hdx end end
                        hdx0=hdx0+_d_hdx0 end end
                        task._Wait(3)
                    sc=sc+_d_sc v=v+_d_v end end
                    task._Wait(75)
                n=n+_d_n end end
            end
