_editor_class["2p3-rose"]=Class(bullet)
_editor_class["2p3-rose"].init=function(self,_x,_y,co,d,a0,mst,trig)
    bullet.init(self,ball_mid,co,true,false)
    self.x,self.y=_x,_y
    self.timer=11
    self.bound=false
    lasttask=task.New(self,function()
        do for _=1,_infinite do
            if IsValid(mst) then
            	self.x=mst.x+d*cos(mst.aa+a0)
            	self.y=mst.y+d*sin(mst.aa+a0)
            	self.rot=mst.aa
            else
            	Kill(self)
            end
            task._Wait(1)
        end end
    end)
    lasttask=task.New(self,function()
        do for _=1,_infinite do
            if not IsValid(_boss) then
                _kill(self,true)
            elseif Dist(self,_boss)<trig then
                ChangeBulletImage(self,rose,co)
            else
                ChangeBulletImage(self,ball_mid,co)
            end
            task._Wait(1)
        end end
    end)
    lasttask=task.New(self,function()
        self.colli=false
        do local tr,_d_tr=(0),(155/60) for _=1,61 do
            _object.set_color(self,"",tr,255,255,255)
            task._Wait(1)
        tr=tr+_d_tr end end
        _object.set_color(self,"",255,255,255,255)
        self.colli=true
    end)
end
koishi_bg=Class(_spellcard_background)

koishi_bg.init=function(self)
    _spellcard_background.init(self)

    _spellcard_background.AddLayer(self,"image:cdbg02b",true,0,0,0,0,0,-0.3,"mul+add",1,1,
        function(self)
        self.task={}
        end,
        function(self)
        task.Do(self)
            self.vx=0.5*cos(self.rot)
            self.vy=-0.5*sin(self.rot)
        end,
        function(self)
        task.Do(self)
        end
    )

    _spellcard_background.AddLayer(self,"image:cdbg02a",false,0,0,0,0,0,0,"",1,1,
        function(self)
        self.task={}
        end,
        function(self)
        task.Do(self)
        end,
        function(self)
        task.Do(self)
        end
    )
end

function koishi_bg:render()
	SetViewMode'world'
	if self.alpha>0 then
		local showboss = IsValid(_boss) and lstg.tmpvar.bg and lstg.tmpvar.bg.hide==true

		for i=#(self.layers),1,-1 do
			local l=self.layers[i]
			SetImageState(l.img,l.blend,Color(l.a*self.alpha,l.r,l.g,l.b))
			if l.tile then
				local w,h=GetTextureSize(l.img)
				for i=-int((208+l.x)/w+0.5),int((208-l.x)/w+0.5) do
					for j=-int((240+l.y)/h+0.5),int((240-l.y)/h+0.5) do
						Render(l.img,l.x+i*w,l.y+j*h,l.rot)
					end
				end
			else
				Render(l.img,l.x,l.y,l.rot,l.hscale,l.vscale)
			end
			l.render(l)
		end

	end
end



koishi_bgk=Class(object)

function koishi_bgk:init()
	self.img='image:cdbg02b'
	self.omiga=-0.3
end

function koishi_bgk:frame()
            self.vx=0.5*cos(self.rot)
            self.vy=-0.5*sin(self.rot)
end

function koishi_bgk:render()
	if self.timer<=60 then
		SetImageState(self.img, 'mul+add', Color(self.timer*255/60,255,255,255))
	end

	local w,h=GetTextureSize(self.img)
	for i=-int((208+self.x)/w+0.5),int((208-self.x)/w+0.5) do
		for j=-int((240+self.y)/h+0.5),int((240-self.y)/h+0.5) do
			Render(self.img,self.x+i*w,self.y+j*h,self.rot)
		end
	end
end
