                    hdx=hdx+_d_hdx end end
                    task._Wait(5)
                end end
                task._Wait(0)
            s=s+_d_s end end
        end)
        do local ap,_d_ap=(-10),(360*8/loop) for _=1,_infinite do
            do local a0,_d_a0=(90+15+20*sin(ap)),(180) for _=1,2 do
                do local a,_d_a=(a0),(15) for _=1,11 do
