_editor_class["3p3-b_cr"].init=function(self,_x,_y,da,ix)
    self.x,self.y=_x,_y
	self.img="img_void"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    local dis = 150
    lasttask=task.New(self,function()
        lasttask=task.New(self,function()
            do local idx,_d_idx=(ix),(0.12) for _=1,_infinite do
                dis=150*cos(idx)
                if IsValid(_boss) then
                    self.aa=_boss.aa+da
                    self.x=-400*cos(_boss.aa+da)+dis*cos(_boss.aa+da-90)+_boss.x0
                    self.y=-400*sin(_boss.aa+da)+dis*sin(_boss.aa+da-90)+_boss.x0
                else
                end
                task._Wait(1)
            idx=idx+_d_idx end end
        end)
        task._Wait(ix/3)
        do for _=1,_infinite do
            last=New(_editor_class["3p3-line"],self.x,self.y,1,self,butterfly,COLOR_PURPLE)
            task._Wait(50)
        end end
    end)
end
_editor_class["3p3-train_cr"]=Class(_object)
_editor_class["3p3-train_cr"].init=function(self,_x,_y,da,d,d0)
    self.x,self.y=_x,_y
	self.img="img_void"
	self.layer=LAYER_ENEMY_BULLET
	self.group=GROUP_GHOST
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=10
	self.maxhp=10
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    local dis = d0
    lasttask=task.New(self,function()
        lasttask=task.New(self,function()
            task._Wait(60)
            do local ap,_d_ap=(0.5),(0.5) for _=1,180 do
                dis=d0+(d-d0)*sin(ap)
                task._Wait(1)
            ap=ap+_d_ap end end
        end)
        lasttask=task.New(self,function()
            do for _=1,_infinite do
                if IsValid(_boss) then
                    self.aa=_boss.aa+da
                    self.x=-400*cos(_boss.aa+da)+dis*cos(_boss.aa+da-90)
                    self.y=-400*sin(_boss.aa+da)+dis*sin(_boss.aa+da-90)
                else
                end
                task._Wait(1)
            end end
        end)
        do for _=1,_infinite do
            last=New(_editor_class["3p3-line"],self.x,self.y,7.5,self,ball_huge,COLOR_YELLOW)
            task._Wait(8)
        end end
    end)
end
_editor_class["3p3-line"]=Class(bullet)
_editor_class["3p3-line"].init=function(self,_x,_y,v,mst,st,co)
    bullet.init(self,st,co,true,des)
    self.x,self.y=_x,_y
    self.dd=0
    self.bound=false
    self.navi=true
    lasttask=task.New(self,function()
        do for _=1,_infinite do
            self.dd=self.dd+v
            if IsValid(mst) and self.dd<800 then
                self.x=mst.x+self.dd*cos(mst.aa)
                self.y=mst.y+self.dd*sin(mst.aa)
            else
                _del(self,true)
            end
            if player.nextspell>0 and Dist(self,player)<80 then Kill(self) end
            task._Wait(1)
        end end
    end)
end
