_tmp_sc=boss.dialog.New(true)
function _tmp_sc:init()
	lstg.player.dialog=false
	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        last=New(_editor_class["3p-mask"],0,0,_)
        LoadMusicRecord("3bossbgm");_play_music("3bossbgm")
        if false then ex.stageframe=0 end
        do local y,_d_y=(-15),(30) local da,_d_da=(120),(-10) for _=1,6 do
            do local x,_d_x=(-72),(144) local s,_d_s=(-1),(2) local a,_d_a=(90+da),(-2*da) for _=1,2 do
                last=New(_editor_class["3op-aim"],x*3,y*1.5,x,y,1,20,a)
            x=x+_d_x s=s+_d_s a=a+_d_a end end
            task._Wait(10)
        y=y+_d_y da=da+_d_da end end
        task.MoveTo(0,112,120,MOVE_DECEL)
        task._Wait(120)
    end)
end
