_tmp_sc=boss.card.New("",1,1,68,3200,{0,0,30},false)
function _tmp_sc:init()
    lasttask=task.New(self,function()
        lasttask=task.New(self,function()
            do for _=1,_infinite do
                task.MoveToPlayer(180,-96,96,112,144,32,48,16,24,MOVE_ACC_DEC,MOVE_X_TOWARDS_PLAYER)
                task._Wait(0)
            end end
        end)
        do for _=1,_infinite do
            do
                --[[ atk1:180f --]]--[[
                --]]
                lasttask=task.New(self,function()
                    do local dx,_d_dx=(90),(-16) for _=1,12 do
                        do local aa,_d_aa=(Angle(self,player)-dx),(dx*2) local co,_d_co=(1),(4) for _=1,2 do
                            last=New(_editor_class["3p-decel"],self.x,self.y,2,aa,co,ball_huge)
                        aa=aa+_d_aa co=co+_d_co end end
                        task._Wait(15)
                    dx=dx+_d_dx end end
                end)
                do local dis,_d_dis=(90),(-2/3) local a,_d_a=(ran:Float(0,360)),(11) local ix,_d_ix=(45),(-1.5) for _=1,60 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local aa,_d_aa=(a),(120) for _=1,3 do
                        last=New(_editor_class["3p-decel"],self.x+cos(aa)*dis,self.y+sin(aa)*dis,1.8,120*((ix/45)^2)*((-1)^ix)+Angle(self,player),3+2*((-1)^ix),grain_a)
                    aa=aa+_d_aa end end
                    task._Wait(3)
                dis=dis+_d_dis a=a+_d_a ix=ix+_d_ix end end
            end
            do
                --[[ atk2:480f --]]--[[
                --]]
                local a = 90
                do local ap,_d_ap=(0),(3) for _=1,240 do
                    local d = 120*sin(ap)
                    a=a-131
                    do local aa,_d_aa=(90+a),(-2*a) local sa,_d_sa=(90+a+90),(-2*a-180) for _=1,2 do
                        last=New(_editor_class["3p-accel"],self.x+d*cos(aa),self.y+d*sin(aa),1,sa,COLOR_RED,heart,30)
                    aa=aa+_d_aa sa=sa+_d_sa end end
                    task._Wait(2)
                ap=ap+_d_ap end end
            end
            do
                --[[ atk1:180f --]]--[[
                --]]
                lasttask=task.New(self,function()
                    do local dx,_d_dx=(90),(-16) for _=1,12 do
                        do local aa,_d_aa=(Angle(self,player)-dx),(dx*2) local co,_d_co=(1),(4) for _=1,2 do
                            last=New(_editor_class["3p-decel"],self.x,self.y,2,aa,co,ball_huge)
                        aa=aa+_d_aa co=co+_d_co end end
                        task._Wait(15)
                    dx=dx+_d_dx end end
                end)
                do local dis,_d_dis=(90),(-2/3) local a,_d_a=(ran:Float(0,360)),(11) local ix,_d_ix=(45),(-1.5) for _=1,60 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local aa,_d_aa=(a),(120) for _=1,3 do
                        last=New(_editor_class["3p-decel"],self.x+cos(aa)*dis,self.y+sin(aa)*dis,1.8,120*((ix/45)^2)*((-1)^ix)+Angle(self,player),3+2*((-1)^ix),grain_a)
                    aa=aa+_d_aa end end
                    task._Wait(3)
                dis=dis+_d_dis a=a+_d_a ix=ix+_d_ix end end
            end
            do
                --[[ atk3:480f --]]--[[
                --]]
                do local s,_d_s=(1),(2) for _=1,3 do
                    do local a,_d_a=(ran:Float(0,360)),(2.5) local v,_d_v=(0.5),(0.25) local ww,_d_ww=(180),(-5) for _=1,12 do
                        do local aa,_d_aa=(a),(24) for _=1,15 do
                            last=New(_editor_class["3p-accel"],self.x,self.y,v,aa,COLOR_RED,grain_a,ww)
                        aa=aa+_d_aa end end
                        task._Wait(5)
                    a=a+_d_a v=v+_d_v ww=ww+_d_ww end end
                    do local a,_d_a=(ran:Float(0,360)),(-2.5) local v,_d_v=(0.5),(0.25) local ww,_d_ww=(180),(-5) for _=1,12 do
                        do local aa,_d_aa=(a),(24) for _=1,15 do
                            last=New(_editor_class["3p-accel"],self.x,self.y,v,aa,COLOR_BLUE,grain_a,ww)
                        aa=aa+_d_aa end end
                        task._Wait(5)
                    a=a+_d_a v=v+_d_v ww=ww+_d_ww end end
                    task._Wait(0)
                s=s+_d_s end end
                task._Wait(120)
            end
            do
                --[[ atk1:180f --]]--[[
                --]]
                lasttask=task.New(self,function()
                    do local dx,_d_dx=(90),(-16) for _=1,12 do
                        do local aa,_d_aa=(Angle(self,player)-dx),(dx*2) local co,_d_co=(1),(4) for _=1,2 do
                            last=New(_editor_class["3p-decel"],self.x,self.y,2,aa,co,ball_huge)
                        aa=aa+_d_aa co=co+_d_co end end
                        task._Wait(15)
                    dx=dx+_d_dx end end
                end)
                do local dis,_d_dis=(90),(-2/3) local a,_d_a=(ran:Float(0,360)),(11) local ix,_d_ix=(45),(-1.5) for _=1,60 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local aa,_d_aa=(a),(120) for _=1,3 do
                        last=New(_editor_class["3p-decel"],self.x+cos(aa)*dis,self.y+sin(aa)*dis,1.8,120*((ix/45)^2)*((-1)^ix)+Angle(self,player),3+2*((-1)^ix),grain_a)
                    aa=aa+_d_aa end end
                    task._Wait(3)
                dis=dis+_d_dis a=a+_d_a ix=ix+_d_ix end end
            end
            do
                --[[ atk4:540f --]]--[[
                --]]
                local iv = 18
                do for _=1,5 do
                    do local x,_d_x=(-144),(288) local acca,_d_acca=(0),(180) for _=1,2 do
                        last=New(_editor_class["3p1-laser"],x,255,3,-90,acca,iv,0,COLOR_RED)
                    x=x+_d_x acca=acca+_d_acca end end
                    task._Wait(18)
                end end
                task._Wait(90)
                do for _=1,5 do
                    do local x,_d_x=(48),(-96) local acca,_d_acca=(0),(180) for _=1,2 do
                        last=New(_editor_class["3p1-laser"],x,255,3,-90,acca,iv,45,COLOR_BLUE)
                    x=x+_d_x acca=acca+_d_acca end end
                    task._Wait(18)
                end end
                task._Wait(90)
                do for _=1,5 do
                    do local x,_d_x=(-220),(440) local acca,_d_acca=(0),(180) local a,_d_a=(45),(90) for _=1,2 do
                        last=New(_editor_class["3p1-laser"],x,-80,3,a,acca,iv,0,COLOR_PURPLE)
                    x=x+_d_x acca=acca+_d_acca a=a+_d_a end end
