_tmp_sc=boss.card.New("",1,1,65,3200,{0,0,31},false)
function _tmp_sc:init()
    lasttask=task.New(self,function()
        task.MoveTo(0,112,60,MOVE_DECEL)
        lasttask=task.New(self,function()
            do for _=1,_infinite do
                task.MoveToPlayer(180,-96,96,112,144,32,48,16,32,MOVE_ACC_DEC,MOVE_X_TOWARDS_PLAYER)
                task._Wait(0)
            end end
        end)
        do for _=1,_infinite do
            do
                --[[ atk1:480f --]]--[[
                --]]
                do local s,_d_s=(1),(-2) for _=1,2 do
                    do local dis,_d_dis=(90),(-2/3) local a,_d_a=(ran:Float(0,360)),(11*s) local ix,_d_ix=(45*s),(-1.5*s) for _=1,60 do
                        PlaySound("tan00",0.1,self.x/256,false)
                        do local aa,_d_aa=(a),(120) for _=1,3 do
                            last=New(_editor_class["3p-decel"],self.x+cos(aa)*dis,self.y+sin(aa)*dis,2.1,120*((ix/45)^2)*((-1)^ix)-90,3+2*((-1)^ix),grain_c)
                        aa=aa+_d_aa end end
                        task._Wait(3)
                    dis=dis+_d_dis a=a+_d_a ix=ix+_d_ix end end
                s=s+_d_s end end
                do local a0,_d_a0=(Angle(self,player)),(0) local idx,_d_idx=(11),(-1) for _=1,9 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local co,_d_co=(1),(4) local v,_d_v=(3),(-1) local da,_d_da=(idx*8),(-3*idx) for _=1,2 do
                        do local s,_d_s=(-1),(2) for _=1,2 do
                            last=New(_editor_class["3p-decel"],self.x,self.y,v,a0+s*da,co,ball_huge)
                        s=s+_d_s end end
                    co=co+_d_co v=v+_d_v da=da+_d_da end end
                    task._Wait(10)
                a0=a0+_d_a0 idx=idx+_d_idx end end
                task._Wait(30)
            end
            do
                --[[ atk2:360f --]]--[[
                --]]
                do local a,_d_a=(180),(14) for _=1,50 do
                    last=New(_editor_class["3p2-eyecenter1"],self.x,self.y,192*cos(a),144+80*sin(a),4,7)
                    task._Wait(6)
                a=a+_d_a end end
                task._Wait(60)
            end
            do
                --[[ atk3:360f --]]--[[
                --]]
                do local sc,_d_sc=(1),(-2/180) local ca0,_d_ca0=(ran:Float(0,360)),(10.2) local sa0,_d_sa0=(ran:Float(0,360)),(-7.4) local idx,_d_idx=(2),(2) for _=1,180 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local ca,_d_ca=(ca0),(180) local sa,_d_sa=(sa0),(180) for _=1,2 do
                        last=New(_editor_class["3p-decel"],self.x+144*cos(ca),self.y+60*sin(ca),2.4,sa,COLOR_PURPLE,grain_c)
                        if idx%10==0 then
                            last=New(_editor_class["3p-decel"],self.x+144*cos(ca),self.y+60*sin(ca),1.8,-sa*2,COLOR_PURPLE,ball_huge)
                        else
                        end
                    ca=ca+_d_ca sa=sa+_d_sa end end
                    task._Wait(2)
                sc=sc+_d_sc ca0=ca0+_d_ca0 sa0=sa0+_d_sa0 idx=idx+_d_idx end end
            end
            do
                --[[ atk4:720f --]]--[[
                --]]
                do local a,_d_a=(ran:Float(0,360)),(127) for _=1,12 do
                    last=New(_editor_class["3p2-eyecenter"],self.x,self.y,4,a)
                    task._Wait(30)
                a=a+_d_a end end
                task._Wait(360)
            end
            task._Wait(0)
        end end
    end)
end
