_editor_class["4-web"].init=function(self,_x,_y,way,s1,s2)
    laser.init(self,COLOR_PURPLE,_x,_y,0,1,1,1,8,8,8)
    lasttask=task.New(self,function()
        self.bound=false
        laser._TurnOn(self,0,false,true)
        do for _=1,_infinite do
            if IsValid(s1) and IsValid(s2) then
                self.x=s1.x; self.y=s1.y; self.rot=Angle(s1,s2); self.ll=Dist(s1,s2); self.l2=self.ll;
            else
                if true then break end
            end
            task._Wait(1)
        end end
        local iv = 20
        if not IsValid(s1) then
            do local sc,_d_sc=(0),(1/(self.ll/iv)) for _=1,self.ll/iv+1 do
                _create_bullet_group(ball_mid,COLOR_PURPLE,self.x+sc*self.ll*cos(self.rot),self.y+sc*self.ll*sin(self.rot),way,0,3,3,0,90,true,0,true,true,0,false,self)
                task._Wait(1)
            sc=sc+_d_sc end end
        else
            do local sc,_d_sc=(1),(-1/(self.ll/iv)) for _=1,self.ll/iv+1 do
                _create_bullet_group(ball_mid,COLOR_PURPLE,self.x+sc*self.ll*cos(self.rot),self.y+sc*self.ll*sin(self.rot),way,0,3,3,0,90,true,0,true,true,0,false,self)
                task._Wait(1)
            sc=sc+_d_sc end end
        end
        _del(self,true)
    end)
end
