                            last=New(_straight,grain_a,COLOR_BLUE,o.x,o.y,2.5,-90,false,0,true,true,0,false,0,0,0,false)
                        hdx=hdx+_d_hdx end end
                    else
                    end
                    task._Wait(5)
                end end
                task._Wait(iv)
            end end
        end)
        do for _=1,_infinite do
            local a0=Angle(self,player)
            if a0%10<5 then a0=a0-a0%10 else a0=a0-a0%10+10 end
            do local vv,_d_vv=(2),(0.05) for _=1,4 do
