                                    last=New(_straight,ball_mid,COLOR_RED,o.x,o.y,vv,aa,false,3,true,true,0,false,0,0,0,false)
                                else
                                    last=New(_editor_class["linked_death"],self.x,self.y,vv,aa,0,_infinite,COLOR_RED,self)
