_editor_class["4-huge_fairy"]=Class(enemy)
_editor_class["4-huge_fairy"].init=function(self,_x,_y,iv,iv2,s)
    enemy.init(self,14,1024,true,false,false)
    self.x,self.y=_x,_y
    self.drop={0,0,20}
    task.New(self,function() self.protect=true task.Wait(60) self.protect=false end)
    lasttask=task.New(self,function()
        self.hitters={}
        self.stay=0
        do local x,_d_x=(-40),(80) for _=1,2 do
            last=New(_editor_class["hitter"],self.x,self.y,x,0,self,"3-hex")
            table.insert(self.hitters,last)
        x=x+_d_x end end
        task.MoveTo(s*100,120,60,MOVE_DECEL)
        lasttask=task.New(self,function()
            do for _=1,_infinite do
                do local v,_d_v=(1.5),(0.2) for _=1,6 do
                    do local a,_d_a=(-60),(-30) for _=1,12 do
                        do local hdx,_d_hdx=(1),(1) for _=1,2 do
                            local o = self.hitters[hdx]
                            last=New(_straight,grain_a,COLOR_RED,o.x,o.y,v,a,false,0,true,true,0,false,0,0,0,false)
                        hdx=hdx+_d_hdx end end
                    a=a+_d_a end end
                    if self.hp<600 or self.stay>720 then self.j=true end
                    if self.j then break end
                    task._Wait(5)
                v=v+_d_v end end
                if self.j then break end
                task._Wait(iv)
            end end
            do local hdx,_d_hdx=(1),(1) for _=1,2 do
                local o = self.hitters[hdx]
                _drop_item(item_point,1,o.x,o.y)
                _kill(o,true)
            hdx=hdx+_d_hdx end end
            self.stay=0
            do for _=1,_infinite do
                last=New(_straight,ball_mid_c,COLOR_BLUE,self.x,self.y,ran:Float(0.5,2.5),90+ran:Float(-45,45),false,0,true,true,0,false,0.03,-90,0,false)
                if self.stay>720 then break end
                task._Wait(iv2)
            end end
            do for _=1,_infinite do
                _create_bullet_group(ball_mid_c,COLOR_DEEP_RED,self.x,self.y,50,0,8,8,ran:Float(0,360),360,false,0,true,true,0,false,self)
                task._Wait(6)
            end end
        end)
        do local ap,_d_ap=(0),(0.75) for _=1,_infinite do
            self.x=s*100*cos(ap)
            self.y=96+24*cos(ap*2.3)
            task._Wait(1)
        ap=ap+_d_ap end end
    end)
end
