_editor_class["4p1-ghost"]=Class(enemy)
_editor_class["4p1-ghost"].init=function(self,_x,_y,a0,d,mst)
    enemy.init(self,27,1,false,true,false)
    self.x,self.y=_x,_y
    self.drop={0,0,0}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    self.group=GROUP_INDES
    local aa = a0
    local dd = 0
    lasttask=task.New(self,function()
        do local ap,_d_ap=(2),(2) for _=1,45 do
            dd=d*sin(ap)
            task._Wait(1)
        ap=ap+_d_ap end end
    end)
    lasttask=task.New(self,function()
        do for _=1,_infinite do
            aa=aa+7
            if IsValid(mst) then
            	self.x=mst.x+dd*cos(aa)
            	self.y=mst.y+dd*sin(aa)
            else
            	Del(self)
            end
            task._Wait(1)
        end end
    end)
end
_editor_class["4p1-center"]=Class(_object)
