_editor_class["4p2-point"]=Class(_object)
_editor_class["4p2-point"].init=function(self,_x,_y,d,a,mst)
    self.x,self.y=_x,_y
	self.img="5-hex"
	self.layer=LAYER_ENEMY
	self.group=GROUP_NONTJT
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=900
	self.maxhp=900
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.a=16; self.b=16; self.mst=mst; self.dd=0; self.aa=a; 
    _connect(mst,self,0,true)
    lasttask=task.New(self,function()
        do local ap,_d_ap=(2),(2) for _=1,45 do
            self.dd=d*sin(ap)
            task._Wait(1)
        ap=ap+_d_ap end end
    end)
