_editor_class["4p2-point"].kill=function(self)
    self.class.base.kill(self)
    New(enemy_death_ef,1,self.x,self.y)
    if IsValid(self.mst) then Damage(self.mst,self.maxhp) end
end
_editor_class["4p2-point"].frame=function(self)
    self.class.base.frame(self)
    self.protect=player.nextspell
    if self.timer<60 then self.protect=max(self.protect,60) end
    if not IsValid(self.mst) then
        _del(self,true)
    else
        self.x=self.mst.x+self.dd*cos(self.aa)
        self.y=self.mst.y+self.dd*sin(self.aa)
    end
end
