	self.img="5-hitter"
	self.layer=LAYER_ENEMY
	self.group=GROUP_NONTJT
	self.hide=false
	self.bound=false
	self.navi=false
	self.hp=_infinite
	self.maxhp=_infinite
	self.colli=true
	self._servants={}
	self._blend,self._a,self._r,self._g,self._b='',255,255,255,255
    self.a=16; self.b=16; 
    self.o1=o1; self.o2=o2; self.sc=sc0;
    _connect(o2,self,1,true)
end
_editor_class["4p2-chain"].kill=function(self)
    self.class.base.kill(self)
    New(enemy_death_ef,1,self.x,self.y)
end
_editor_class["4p2-chain"].frame=function(self)
    self.class.base.frame(self)
    self.protect=player.nextspell
    if self.timer<60 then self.protect=max(self.protect,60) end
    if not IsValid(self.o1) then
        _del(self,true)
    elseif not IsValid(self.o2) then
        _kill(self,true)
    else
        self.x=self.o1.x*self.sc+self.o2.x*(1-self.sc)
        self.y=self.o1.y*self.sc+self.o2.y*(1-self.sc)
    end
end
