_editor_class["4p3-act"]=Class(enemy)
_editor_class["4p3-act"].init=function(self,_x,_y,v,a,x2,y2,mst)
    enemy.init(self,13,_infinite,false,false,false)
    self.x,self.y=_x,_y
    self.drop={0,0,0}
    task.New(self,function() self.protect=true task.Wait(1) self.protect=false end)
    self.imgs={}
    for i=1,12 do self.imgs[i]='image:fairy_zombie'..i end
    self.mst=mst
    self.bound=false
    lasttask=task.New(self,function()
        SetV2(self,v,a,false,false)
        task._Wait(30)
        do for _=1,60 do
            _set_a(self,0.05,0,true)
            task._Wait(1)
        end end
        _set_a(self,0,0,false)
        SetV2(self,0,0,false,false)
        if IsValid(mst) then
            PlaySound("kira00",0.1,self.x/256,false)
            do local a,_d_a=(Angle(mst,player)),(90) for _=1,4 do
                last=New(_straight,water_drop,COLOR_RED,self.x,self.y,0,a,false,0,true,true,0,false,0.01,'original',1,false)
            a=a+_d_a end end
        else
        end
        task._Wait(15)
        task.MoveTo(x2,y2,45,MOVE_DECEL)
        self.bound=true
        local a0
        if IsValid(mst) then
            a0 = Angle(mst,player)
        else
        end
        _set_a(self,0.03,a0+180,false)
        do for _=1,_infinite do
            PlaySound("tan00",0.01,self.x/256,false)
            last=New(_straight,grain_b,COLOR_BLUE,self.x,self.y,4,a0,false,0,true,true,0,false,0,0,0,false)
            task._Wait(8)
        end end
    end)
end
