        		table.insert(xt,i*j)
        	end
        end
        
        local yt={}
        for i=1,2 do
        	for j=-180,180,45 do
        		table.insert(yt,j)
        	end
        end
        
        local it={}
        for i=1,18 do it[i]=i end
        self.hitters={}
        local ra0 = ran:Float(0,360)
        do local d,_d_d=(30),(30) local a0,_d_a0=(ra0),(30) for _=1,3 do
            do local a,_d_a=(a0),(60) for _=1,6 do
                last=New(_editor_class["hitter"],self.x,self.y,d*cos(a),d*sin(a),self,'5-hitter')
                table.insert(self.hitters,last)
            a=a+_d_a end end
        d=d+_d_d a0=a0+_d_a0 end end
        lasttask=task.New(self,function()
            local dda = -0.25
            local da = 0
            do for _=1,_infinite do
                dda=dda+0.002
                da=da+dda
                do local hdx0,_d_hdx0=(1),(6) local a0,_d_a0=(ra0),(30) local d,_d_d=(30),(30) for _=1,3 do
                    do local a,_d_a=(a0),(60) local hdx,_d_hdx=(hdx0),(1) for _=1,6 do
                        local o = self.hitters[hdx]
                        o.xx=d*cos(a+da)  o.yy=d*sin(a+da)
                    a=a+_d_a hdx=hdx+_d_hdx end end
                hdx0=hdx0+_d_hdx0 a0=a0+_d_a0 d=d+_d_d end end
                task._Wait(1)
            end end
        end)
        task.MoveTo(0,112,60,MOVE_DECEL)
        do for _=1,_infinite do
            do
                lasttask=task.New(self,function()
                    do for _=1,4 do
                        task.MoveToPlayer(120,-96,96,112,144,32,48,16,32,MOVE_ACC_DEC,MOVE_X_TOWARDS_PLAYER)
                        task._Wait(0)
                    end end
                end)
                lasttask=task.New(self,function()
                    task._Wait(360)
                    do
                        do local hdx0,_d_hdx0=(1),(6) local n,_d_n=(1),(2) for _=1,3 do
                            do local v,_d_v=(2.5),(0.1) for _=1,45 do
                                PlaySound("tan00",0.1,self.x/256,false)
                                do local hdx,_d_hdx=(hdx0),(1) for _=1,6 do
                                    local o = self.hitters[hdx]
                                    do local da,_d_da=(-60*(n-1)/2),(60) for _=1,n do
                                        last=New(_straight,ball_mid,COLOR_RED,o.x,o.y,v,Angle(self,player)+da,false,0,true,true,0,false,0,0,0,false)
                                    da=da+_d_da end end
                                hdx=hdx+_d_hdx end end
                                task._Wait(2)
                            v=v+_d_v end end
                            task.MoveToPlayer(30,-96,96,112,144,16,32,8,16,MOVE_DECEL,MOVE_X_TOWARDS_PLAYER)
                            task._Wait(0)
                        hdx0=hdx0+_d_hdx0 n=n+_d_n end end
                    end
                end)
                do local dv,_d_dv=(0),(0.02) for _=1,30 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local hdx0,_d_hdx0=(7),(6) local co,_d_co=(COLOR_RED),(3) local v,_d_v=(3.6),(-0.9) for _=1,2 do
                        do local hdx,_d_hdx=(hdx0),(1) for _=1,6 do
                            local o = self.hitters[hdx]
                            do local a,_d_a=(Angle(self,o)-30),(30) for _=1,3 do
