    self.x,self.y=0,-384
    self.chains={}
    self.points={}
    self.droplife=false
    do local s,_d_s=(-1),(2) for _=1,2 do
        last=New(_editor_class["5p0-point"],self.x,self.y,60,90+s*15,self,'3-hex')
        local o1=last
        lasttask=task.New(last,_editor_tasks["5p0-o1task"](s))
        table.insert(self.points,last)
        _connect(self,last,1,true)
        last=New(_editor_class["5p0-point"],self.x,self.y,300,90+s*150,o1,'3-hex')
        local o2=last
        lasttask=task.New(last,_editor_tasks["5p0-o2task"](s))
        table.insert(self.points,last)
        do local sc,_d_sc=(1/8),(1/8) for _=1,7 do
            last=New(_editor_class["5p0-chain"],self.x,self.y,o1,o2,sc)
            table.insert(self.chains,last)
        sc=sc+_d_sc end end
    s=s+_d_s end end
    lasttask=task.New(self,function()
        task.MoveTo(0,144,90,MOVE_DECEL)
        task.MoveTo(0,96,30,MOVE_ACC_DEC)
    end)
    lasttask=task.New(self,function()
        task._Wait(90)
        local itv=60
        local way = 3
        do
            lasttask=task.New(self,function()
                do for _=1,_infinite do
                    do local co,_d_co=(COLOR_RED),(4) local pdx,_d_pdx=(1),(2) for _=1,2 do
                        PlaySound("tan00",0.1,self.x/256,false)
                        local o = self.points[pdx]
                        do local a,_d_a=(Angle(self,player)-2*(way-1)/2),(2) for _=1,way do
                            last=New(_straight,water_drop,co,o.x,o.y,3,a,false,0,true,true,0,false,0,0,0,false)
                        a=a+_d_a end end
                        task._Wait(itv)
                        task._Wait(0)
                    co=co+_d_co pdx=pdx+_d_pdx end end
                    task._Wait(0)
                end end
            end)
        end
        do
            do for _=1,_infinite do
                local o = self.chains[ran:Int(1,14)]
                if IsValid(o) then
                    last=New(_straight,grain_b,COLOR_BLUE,o.x,o.y,ran:Float(1.5,3),-90+ran:Float(-5,5),false,0,true,true,0,false,0,0,0,false)
                else
                    if true then break end
                end
                task._Wait(2)
            end end
        end
        do
            _clear_bullet(true,false)
            itv=40  way=5
            do for _=1,_infinite do
                local np = 2
                do local pdx,_d_pdx=(2),(2) for _=1,2 do
                    local o = self.points[pdx]
                    if IsValid(o) then
                        np=np-1
                        local sc = ran:Int(1,7)/8
                        last=New(_straight,grain_b,COLOR_RED,o.x*sc+self.x*(1-sc),o.y*sc+self.y*(1-sc),ran:Float(1.5,3),-90+ran:Float(-5,5),false,0,true,true,0,false,0,0,0,false)
                    else
                    end
                pdx=pdx+_d_pdx end end
                if np==2 then break end
                task._Wait(2)
            end end
        end
        do
            self.droplife=true
            itv=10  way=9
        end
    end)
end
