_editor_class["5p2-cog"].frame=function(self)
    self.class.base.frame(self)
    if IsValid(self.mst) then
        self.rot=self.rot+self.s*1/2
        self.x=self.mst.x+self.mst.sc*120*cos(self.rot)
        self.y=self.mst.y+self.mst.sc*120*sin(self.rot)
        if self.y<255 and self.timer>240 then
            	local dt = 72 --激光触发范围
            	self.create=0 --当前帧是否触发
            	local dhead = Dist(self.headx, self.heady, player.x,player.y) --head与玩家的距离
            	local dself = Dist(self,player) --node与玩家的距离
            	local ahead = Angle(self.headx, self.heady, player.x, player.y) --head对玩家的角度
            	local aself = Angle(self,player) --node对玩家的角度
            	if dself<dt then --node在范围内：直接触发
            		self.create=1
            		self.l2=0
            	else
            		if dhead<dt then --node不在范围内，head在范围内
            			self.create=1
            			local fact = 0.5
            			local df = 0.5
            			for i=1,10 do --寻找距离交点最近的点10次
            				df=df/2
            				local hx = self.x+self.l2*cos(self.rot)*fact
            				local hy = self.y+self.l2*sin(self.rot)*fact
            				if Dist(hx,hy,player.x,player.y)<dt then fact=fact-df else fact=fact+df end
            			end
            			self.l2=self.l2*fact
            		else --两点均不在范围内：使用激光碰撞判定获得激光上一个在范围内的点
            			local x=player.x-self.x
            			local y=player.y-self.y
            			local rot=self.rot
            			x,y=x*cos(rot)+y*sin(rot),y*cos(rot)-x*sin(rot)
            			y=abs(y)
            			if x>0 and x<self.l2 then
            				if y<x/self.l2*dt then
            					self.create=1
            					self.l2=x
            					local fact = 0.5
            					local df = 0.5
            					for i=1,10 do --寻找距离交点最近的点10次
            						df=df/2
            						local hx = self.x+self.l2*cos(self.rot)*fact
            						local hy = self.y+self.l2*sin(self.rot)*fact
            						if Dist(hx,hy,player.x,player.y)<dt then fact=fact-df else fact=fact+df end
            					end
            					self.l2=self.l2*fact
            				end
            			end
            		end
            	end
            
            	self.headx=self.x+self.l2*cos(self.rot)
            	self.heady=self.y+self.l2*sin(self.rot)
            if self.create>0 then
                if self.timer%self.iv==0 then
                    local x,y = self.x+self.l2*cos(self.rot), self.y+self.l2*sin(self.rot)
                    if Dist(x,y,player.x,player.y)>8 then
                        last=New(_straight,mildew,COLOR_PURPLE,self.x+self.l2*cos(self.rot), self.y+self.l2*sin(self.rot),0,self.rot,false,ran:Sign()*3,true,true,0,false,0.0075,'original',0,false)
                    else
                    end
                else
                end
            else
                if self.y>=-255 then self.l2=min(666,self.l2+3) end
            end
            if self.y<-255 then self.l2=max(0,min(self.l2*0.96,self.l2-8)) end
        else
        end
    else
        _del(self,true)
    end
end
