_editor_class["okuu:Normal"]=Class(boss)
_editor_class["okuu:Normal"].cards={}
_editor_class["okuu:Normal"].name="okuu"
_editor_class["okuu:Normal"].init=function(self,cards)
    boss.init(self,0,600,"okuu",cards,New(spellcard_background),"Normal")
	self.ani_intv=8
	for i=1,4 do self['img'..i]={} end
	self.nn={4,3,3,4}
	self.mm={1,1,2}
	for i=2,4 do self['ani'..i]=self.nn[i]-self.mm[i-1] end
	for i=1,4 do
		for j=1,self.nn[i] do
			self['img'..i][j]='anonymous:'.."assets/graphics/stg5enm.png"..i..j
		end
	end
end
