	_dialog_can_skip=true
	self.dialog_displayer=New(dialog_displayer)
    task.New(self,function()
        LoadMusicRecord("5bossbgm");_play_music("5bossbgm")
        if false then ex.stageframe=0 end
        lasttask=task.New(self,function()
            New(boss_cast_ef,0,0)
            task._Wait(60)
            do local v,_d_v=(1),(0.2) for _=1,45 do
                do local a,_d_a=(-90),(360/36) for _=1,36 do
                    last=New(_straight,ball_big,COLOR_YELLOW,0,0,v,a,false,0,true,true,0,false,0,0,0,false)
                    _object.set_color(last,"mul+add",255,255,255,255)
                a=a+_d_a end end
                task._Wait(4)
            v=v+_d_v end end
        end)
        task._Wait(180)
        self.x=0 self.y=0
        task._Wait(60)
    end)
end
