function _tmp_sc:init()
    lasttask=task.New(self,function()
        lasttask=task.New(self,function()
            self.aa=-90
            lasttask=task.New(self,function()
                do for _=1,_infinite do
                    local ta = Angle(self,player)
                    local s = -sign(math.floor((ta-self.aa)%360-180))
                    self.aa=self.aa+s*0.2
                    task._Wait(1)
                end end
            end)
        end)
        self.hitters={}
        self.orbiters={}
        do local x,_d_x=(-100),(200) local a0,_d_a0=(ran:Float(0,360)),(0) local s,_d_s=(-1),(2) for _=1,2 do
            last=New(_editor_class["hitter"],self.x,self.y,x,0,self,'5-hex')
            local o = last  table.insert(self.hitters,o)
            do local a,_d_a=(s*a0),(120) for _=1,3 do
                last=New(_editor_class["5p1-orbit"],self.x,self.y,80,a,s,o)
                table.insert(self.orbiters,last)
                _connect(self,last,1,true)
            a=a+_d_a end end
        x=x+_d_x a0=a0+_d_a0 s=s+_d_s end end
        do for _=1,_infinite do
            do
                task.MoveTo(0,112,60,MOVE_NORMAL)
                lasttask=task.New(self,function()
                    do for _=1,28 do
                        do for _=1,10 do
                            do local odx,_d_odx=(1),(1) for _=1,6 do
                                local o = self.orbiters[odx]
                                do local v,_d_v=(2.1),(-0.2) for _=1,2 do
                                    last=New(_straight,ball_mid,COLOR_RED,o.x,o.y,v,o.aa,false,3,true,true,0,false,0,0,0,false)
                                v=v+_d_v end end
                            odx=odx+_d_odx end end
                            task._Wait(2)
                        end end
                        task._Wait(10)
                    end end
                end)
                do local v,_d_v=(2),(0) for _=1,105 do
                    PlaySound("tan00",0.1,self.x/256,false)
                    do local da0,_d_da0=(0),(5.73) local vv,_d_vv=(v),(-v*0.08) for _=1,1 do
                        do local odx0,_d_odx0=(1),(3) local da,_d_da=(da0),(-2*da0) for _=1,2 do
                            do local odx,_d_odx=(odx0),(1) for _=1,3 do
                                local o = self.orbiters[odx]
                                last=New(_straight,water_drop,COLOR_RED,o.x,o.y,vv,o.aa+da,false,0,true,true,0,false,0,0,0,false)
                            odx=odx+_d_odx end end
                        odx0=odx0+_d_odx0 da=da+_d_da end end
                    da0=da0+_d_da0 vv=vv+_d_vv end end
                    task._Wait(8)
                v=v+_d_v end end
                task._Wait(60)
            end
            do
                lasttask=task.New(self,function()
                    do for _=1,6 do
                        task._Wait(30)
                        PlaySound("don00",1,self.x/256,false)
                        do local dsc,_d_dsc=(1),(-1/60) local v,_d_v=(3),(0) for _=1,30 do
                            local ra= ran:Float(0,360)
                            last=New(_editor_class["5p1-nuke"],self.x+dsc*180*cos(ra),self.y+dsc*80*sin(ra),v,ran:Float(0,360),ran:Float(0.15,0.2))
                            task._Wait(2)
                        dsc=dsc+_d_dsc v=v+_d_v end end
                        task._Wait(26)
                    end end
                end)
                do local da,_d_da=(0),(16.36) for _=1,72 do
                    do local v2,_d_v2=(5),(-0.25) for _=1,10 do
                        do local s,_d_s=(1),(-2) local hdx,_d_hdx=(1),(1) for _=1,2 do
                            local o = self.hitters[hdx]
                            do local ca,_d_ca=(-90-s*da),(180) for _=1,2 do
                                last=New(_editor_class["5p1-long"],o.x,o.y,3,v2,ca,3,s)
                            ca=ca+_d_ca end end
                        s=s+_d_s hdx=hdx+_d_hdx end end
                        task._Wait(1)
                    v2=v2+_d_v2 end end
                    task._Wait(0)
                da=da+_d_da end end
                task._Wait(90)
                do local hdx,_d_hdx=(1),(1) local odx,_d_odx=(1),(3) for _=1,2 do
                    local o = self.hitters[hdx]
                    local oa = self.orbiters[odx]
                    do local d,_d_d=(-80),(80) local da,_d_da=(0),(30) for _=1,2 do
                        do local a0,_d_a0=(oa.aa+da),(60) for _=1,6 do
                            do local a,_d_a=(a0-15),(6) for _=1,6 do
                                last=New(_straight,ball_huge,COLOR_YELLOW,o.x+d*cos(a),o.y+d*sin(a),4,a,false,0,true,true,0,false,0,0,0,false)
                            a=a+_d_a end end
                        a0=a0+_d_a0 end end
                    d=d+_d_d da=da+_d_da end end
                    task._Wait(75)
                hdx=hdx+_d_hdx odx=odx+_d_odx end end
            end
            do
                lasttask=task.New(self,function()
                    do for _=1,12 do
                        local a0 = Angle(self,player)
                        do local n,_d_n=(1),(1) for _=1,3 do
                            do local da,_d_da=(-3*(n-1)/2),(3) for _=1,n do
                                last=New(_straight,ball_mid,COLOR_RED,self.x,self.y,3,a0+da,false,0,true,true,0,false,0,0,0,false)
                            da=da+_d_da end end
                            task._Wait(5)
                        n=n+_d_n end end
                        do local n,_d_n=(2),(-1) for _=1,2 do
                            do local da,_d_da=(-3*(n-1)/2),(3) for _=1,n do
                                last=New(_straight,ball_mid,COLOR_RED,self.x,self.y,3,a0+da,false,0,true,true,0,false,0,0,0,false)
                            da=da+_d_da end end
                            task._Wait(5)
                        n=n+_d_n end end
                        task._Wait(20)
                    end end
                    do local s,_d_s=(-1),(2) local odx0,_d_odx0=(1),(3) local hdx,_d_hdx=(1),(1) for _=1,2 do
                        local lt = {}
                        PlaySound("don00",1,(s*100)/256,false)
                        do local w,_d_w=(120),(-2) local n,_d_n=(1),(1) for _=1,60 do
                            local ot = {}
                            lt={}
                            do local odx,_d_odx=(odx0),(1) for _=1,3 do
                                local o = self.orbiters[odx]
                                last=New(_editor_class["5p1-carrier"],o.x,o.y,12,o.aa)
                                _connect(self,last,0,true)
                                table.insert(ot,last)
                            odx=odx+_d_odx end end
                            do local idx,_d_idx=(1),(1) for _=1,3 do
                                last=New(_editor_class["5p1-carried"],self.x,self.y,ot[idx%3+1],ot[(idx+1)%3+1],self.hitters[hdx],w)
                                table.insert(lt,last)
                            idx=idx+_d_idx end end
                            task._Wait(1)
                        w=w+_d_w n=n+_d_n end end
                        do local idx,_d_idx=(1),(1) for _=1,3 do
                            lasttask=task.New(lt[idx],_editor_tasks["5p1-carried_cr"](7,2))
                        idx=idx+_d_idx end end
                        task._Wait(0)
                    s=s+_d_s odx0=odx0+_d_odx0 hdx=hdx+_d_hdx end end
                end)
                do for _=1,12 do
                    do local a0,_d_a0=(Angle(self,player)),(0) for _=1,15 do
                        PlaySound("kira00",0.1,self.x/256,false)
                        do local odx,_d_odx=(1),(1) for _=1,6 do
                            local o = self.orbiters[odx]
                            last=New(_straight,ball_big,COLOR_BLUE,o.x,o.y,0,a0+5*cos(o.aa),false,0,true,true,0,false,0.03,'original',0,false)
                            _object.set_color(last,"mul+add",255,255,255,255)
                        odx=odx+_d_odx end end
                        task._Wait(2)
                    a0=a0+_d_a0 end end
                    task._Wait(30)
                end end
                task._Wait(120)
            end
            task._Wait(0)
        end end
    end)
end
